def handle(app, svc):
    """Northwind partner handler.

    Northwind uses the network's current API (v2): svc.apply returns
    {"api_version": 2, "result": {"outcome": "approved"|"declined"|"manual_review",
    "credit_limit": <int>}}.

    Outcome mapping (spec section 3):
      approved      -> issue, limit = credit_limit
      declined      -> decline, limit 0
      manual_review -> queue_review, limit 0  (spec: do NOT decline it)

    Network rule (spec): a self_employed applicant with requested_limit above
    6000 must be queue_review instead of issued; a decline stays a decline.
    """
    resp = svc.apply(app)

    # API v2 shape (current). Be defensive about the nested shape.
    result = resp.get("result", {}) if isinstance(resp, dict) else {}
    outcome = result.get("outcome")
    credit_limit = result.get("credit_limit", 0)
    if not isinstance(credit_limit, int):
        try:
            credit_limit = int(credit_limit)
        except (TypeError, ValueError):
            credit_limit = 0

    # Base mapping per spec section 3 / changelog.
    if outcome == "approved":
        action = "issue"
        limit = credit_limit
    elif outcome == "declined":
        action = "decline"
        limit = 0
    else:
        # manual_review (or anything unexpected) -> queue_review, never decline.
        action = "queue_review"
        limit = 0

    # Network rule: self_employed + requested_limit > 6000 must not be issued.
    if action == "issue":
        try:
            requested = int(app.get("requested_limit", 0))
        except (TypeError, ValueError):
            requested = 0
        if app.get("employment") == "self_employed" and requested > 6000:
            action = "queue_review"
            limit = 0

    return {"action": action, "limit": limit}
